Translate("deDE", "burning-steppes", {
	title = "Brennende Steppe",
	aliases = { "die Steppe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Brennende Steppe ist ein Land aus Asche. Zwischen dem {link:redridge-mountains}Rotkammgebirge{/link} im Süden und der rauchenden Masse des {link:blackrock-mountain}Blackrock{/link} im Nordwesten liegt das Land schwarz und zerrissen, durchzogen von Strömen geschmolzenen Gesteins. Nichts Grünes wächst hier lange. Die Luft schmeckt nach Schlacke, der Himmel glüht nachts rot, und der Boden selbst ist warm unter den Füßen. Doch die Steppe ist keine leere Öde. Sie ist der einzige Landweg zwischen dem {link:kingdom-of-stormwind}Königreich Stormwind{/link} und den Zwergenlanden von Khaz Modan jenseits des Berges, und jede Macht, die nach diesem Weg trachtet, ist gekommen, um ein Stück davon zu halten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Steppe war nicht immer eine Öde. Die Gelehrten von {link:morgan-s-vigil}Morgans Wacht{/link} sagen, das Land sei einst das nördliche Ende des Rotkammgebirges gewesen, mit denselben roten Graten und kalten Bächen, die {link:lakeshire}Seenhain{/link} noch heute kennt. Es waren die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}, die dem ein Ende setzten. Nach dem Krieg der drei Zwergenklans aus {link:ironforge}Ironforge{/link} verbannt, erbauten sie in diesen Bergen eine Stadt und benannten sie nach ihrem Zauberthan {link:ruins-of-thaurissan}Thaurissan{/link}. Als die Bronzebeards und die Wildhammer gegen sie zogen, griff Thaurissan in die Tiefen der Welt nach einer Waffe, und stattdessen rief er {red:ragnaros}Ragnaros{/red} den Feuerfürsten herbei. Das Erscheinen des Ragnaros ließ die Berge meilenweit schmelzen. Die Stadt der Dunkeleisenzwerge wurde zerstört, ein Vulkan erhob sich, wo das Land aufgerissen war, und das Land südlich davon brannte. Es hat nie aufgehört zu brennen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die Steppe gehört keiner Krone. Die {link:orcs}Orcs{/link} des {link:blackrock-clan}Blackrockklans{/link} halten das Herz des Landes von ihrer Festung unter dem Berg aus, und ihre Kriegstrupps ziehen südwärts durch den {link:blackrock-pass}Blackrockpass{/link}, um {link:lakeshire}Seenhain{/link} heimzusuchen. {link:ogres}Oger{/link} der Firegut bewachen für sie die Minen am {link:dreadmaul-rock}Schreckensfels{/link}. Schwarze Drachkin nisten entlang der östlichen Klippen und in den versengten Hügeln des Südwestens. Spione und Feuerläufer der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} streifen noch immer durch die Ruinen ihrer alten Stadt, und lebendiges Feuer und lebendiger Stein wandeln über die Ebenen.

Gegen all dies hält {link:kingdom-of-stormwind}Stormwind{/link} einen einzigen Außenposten: {link:morgan-s-vigil}Morgans Wacht{/link}, auf einem Grat im Südosten, wo {link:marshal-maxwell}Marschall Maxwell{/link} mit einer Handvoll Soldaten und Gelehrter ausharrt und auf einen Regenten wartet, der kein Heer schickt. Der Marschall, der sie einst befehligte, {red:reginald-windsor}Reginald Windsor{/red}, ist im Berg verschollen, mitsamt all seinem gesammelten Wissen über den Feind. Weit im Norden, unter dem Grat, bietet ein kleines Lager am {link:flame-crest}Flammenkamm{/link} Händlern, Suchenden und Ausgestoßenen aller Völker Schutz und gibt der {link:horde}Horde{/link} einen eigenen Stützpunkt.

Was die {link:the-night-watch}Wächter{/link} der Wacht zu erkennen beginnen, ist, dass die Orcs nicht die wahren Herren der Steppe sind. Etwas Älteres und weit Listigeres lenkt die {link:blackrock-mountain}Blackrock{/link} aus dem Hintergrund, und seine Klauen reichen vielleicht weiter, als irgendjemand in {link:stormwind-city}Stormwind{/link} glauben möchte.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Blackrockorcs.{/b} Der älteste der Kriegsklans, der noch immer die Wege der alten {link:horde}Horde{/link} befolgt. Ihre Soldaten, Zauberer und Hexenmeister füllen die mittleren Ebenen und die Festung unter dem Berg, und ihre Worgs laufen mit ihnen.
• {b}Die {link:ogres}Oger{/link} der Firegut.{/b} Verbündete der {link:blackrock-mountain}Blackrock{/link}; sie halten den {link:dreadmaul-rock}Schreckensfels{/link} und halten seine Nachschubwege offen.
• {b}Die schwarzen Drachkin.{/b} Brutlinge, Drachenbrut, Wyrmkin und Drachen streifen über die östlichen Klippen und den {link:terror-wing-path}Schreckenspfad{/link}. Ihre flammenschuppigen Verwandten halten {link:draco-dar}Draco'dar{/link} im Südwesten.
• {b}Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}.{/b} Spione, Agenten und Feuerläufer Thaurissans wachen über die zerstörte Stadt, und von ihnen erschaffene Kriegshäscher streifen durch die Asche.
• {b}Die Kinder des Feuers.{/b} Obsidian- und Flammenelementare wandern durch das Land, Überreste des Feuers, das es erschuf.
• {b}Das Volk von {link:morgan-s-vigil}Morgans Wacht{/link}.{/b} Soldaten Stormwinds, ein nachtelfischer Späher, eine Gnomin der Magier und eine Agentin des Adels, die alle einen einzigen Grat halten.
• {b}Die Leute vom {link:flame-crest}Flammenkamm{/link}.{/b} Goblinhändler, ein gnomischer Schatzsucher, ein elfischer Verzauberer, ein betrunkener {link:dwarves}Zwerg{/link} und die {link:orcs}Orcs{/link} der Horde, die gemeinsam unter dem nördlichen Grat Schutz suchen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das grüne Land.{/b} Vor langer Zeit war die Steppe Teil des Rotkammgebirges, und die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} errichteten ihre Stadt zwischen seinen Gipfeln.
• {b}Die Beschwörung.{/b} Zauberthan {link:ruins-of-thaurissan}Thaurissan{/link} rief Ragnaros herbei. Die Berge schmolzen, der {link:blackrock-mountain}Blackrock{/link} wurde geboren, und das Land wurde zur Brennenden Steppe.
• {b}Die Kriege der {link:horde}Horde{/link}.{/b} Die {link:orcs}Orcs{/link} machten den Berg zu ihrer Festung. Im {link:second-war}Zweiten Krieg{/link} zog die {link:alliance}Allianz{/link} nach Norden, um ihn zu belagern, und am Fuß der Blackrockspitze erschlug {link:orgrim-doomhammer}Orgrim Doomhammer{/link} {link:anduin-lothar}Anduin Lothar{/link}. {link:turalyon}Turalyon{/link} übernahm Lothars Befehl und zerschlug die Horde.
• {b}Die Rückkehr der Blackrock.{/b} Die Blackrock, die den Internierungslagern entkamen, kehrten zu dem Berg zurück, der ihren Namen trägt, und seither halten sie die Steppe.
• {b}Die Gegenwart.{/b} Marschall Windsor sammelte Beweise dafür, wer die Blackrock wirklich befehligt, und er verschwand, bevor er sie überbringen konnte. {link:morgan-s-vigil}Morgans Wacht{/link} hält Ausschau und wartet.]=],
		},
		{
			title = "Überlieferungen der Steppe",
			text = [=[• Die Relikte Thaurissans, die überall in der zerstörten Stadt liegen, sollen Erinnerungen an die Beschwörung bewahren. Wer sie berührt, trägt Visionen von dem Tag davon, an dem der Berg geboren wurde.
• In der Wacht sprechen die Soldaten von Ironfoe, dem Hammer, den Marschall Windsor trug. Sie sagen, ein Meister der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} habe ihn für einen seiner Vorfahren geschmiedet, und er habe einen Zwilling.
• Die {link:orcs}Orcs{/link} der Steppe züchten und richten ihre Worgs in der Blackrockspitze ab. Wie viele auch erschlagen werden, die Rudel scheinen nie kleiner zu werden.
• Im Lager am {link:flame-crest}Flammenkamm{/link} streiten ein Goblin und ein {link:gnomes}Gnom{/link} über Dracheneier, ein Goblin verkauft Worgwelpen an die Reichen, und eine Schwester jagt ihren eigenen Bruder wegen des Kopfgeldes auf ihn.]=],
		},
	},
})

Translate("deDE", "morgan-s-vigil", {
	title = "Morgans Wacht",
	aliases = { "die Wacht" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Morgans Wacht ist der letzte Außenposten {link:kingdom-of-stormwind}Stormwinds{/link} in der Brennenden Steppe. Sie steht auf einem hohen Grat im Südosten, über einem Hang, auf dem schwarze Drachkin umherstreifen, und blickt über das ganze brennende Land hinweg zum Berg. Ein Greifenmeister hält Tiere für den Heimflug bereit. {link:marshal-maxwell}Marschall Maxwell{/link} führt hier den Befehl, mit wenigen Soldaten, einem nachtelfischen Späher, einer von den Magiern gesandten Gnomin und einer Dame im Dienst eines Grafen. Einst waren sie die Truppe von Marschall Windsor. Nun sind sie einfach das, was übrig ist.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik berichtet, wer {link:morgan-stern}Morgan{/link} war oder warum die Wacht diesen Namen trägt.]=],
		},
	},
})

Translate("deDE", "flame-crest", {
	title = "Flammenkamm",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Flammenkamm ist ein kleines Lager in einer Höhle unter dem nördlichen Grat der Steppe, nordwestlich des {link:dreadmaul-rock}Schreckensfels{/link}. Die {link:horde}Horde{/link} unterhält hier einen Windreitermeister und einen Gastwirt, doch das Lager gehört keinem einzelnen Volk. Goblins handeln mit Haustieren und jagen ihre eigene Sippe. Ein {link:gnomes}Gnom{/link} folgt alten Zwergenlegenden auf der Suche nach Reichtum. Ein Elf aus {link:quel-thalas}Quel'Thalas{/link} verkauft Verzauberungen zu einem bitteren Preis. Ein betrunkener {link:dwarves}Zwerg{/link} namens {link:ragged-john}Ragged John{/link} sitzt unter ihnen, und wer Marschall Windsor sucht, kommt, um seine Geschichte zu hören.]=],
		},
	},
})

Translate("deDE", "blackrock-stronghold", {
	title = "Festung der Blackrock",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Festung der Blackrock ist die Burg der Blackrockorcs auf den offenen Ebenen südlich des Berges. Ihre Schlachtmeister drillen hier die Soldaten des Klans, und ihre Hexenmeister halten ihre Feuer Tag und Nacht am Brennen. Von der Festung aus marschieren die Kriegstrupps südwärts in Richtung {link:redridge-mountains}Rotkamm{/link}. Sie ist auch eine Zuflucht für jene, die die {link:horde}Horde{/link} {link:thrall}Thralls{/link} verraten: Der {link:orcs}Orc{/link} {link:grark-lorkrub}Grark Lorkrub{/link} sitzt hier unter dem Schutz des Klans und hält sich für sicher. Ein Blackrocksoldat namens Ugkragg verweilt nahe ihren Mauern, beschämt durch eine Niederlage, die keine Aufzeichnung nennt.]=],
		},
	},
})

Translate("deDE", "dreadmaul-rock", {
	title = "Schreckensfels",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schreckensfels ist ein großer Felssporn im Osten der Steppe, reich an Erz und durchzogen von Höhlen und Minen. Die {link:ogres}Oger{/link} der Firegut halten ihn für die {link:blackrock-mountain}Blackrock{/link}, und ihre Magier und Rohlinge bewachen jeden Pfad. Ein Trupp der {link:horde}Horde{/link} kam hierher, um zu erfahren, welche seltsamen Riten die Oger vollzogen. Keiner von ihnen kehrte zurück. Eine von ihnen, Sha'ni Proudtusk, wurde vom Oger {link:krom-grul}Krom'Grul{/link} auf einem Altar auf dem Gipfel angekettet, und ihr Geist hat diesen Ort nicht verlassen. Auf der Spitze eben dieses Felsens pflanzten die Soldaten von {link:morgan-s-vigil}Morgans Wacht{/link} einst den Kopf eines Ogerlords auf eine Pike.]=],
		},
	},
})

Translate("deDE", "ruins-of-thaurissan", {
	title = "Die Ruinen von Thaurissan",
	aliases = { "Thaurissan", "die Ruinen von Thaurissan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Thaurissan sind alles, was über der Erde von der ersten Stadt der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} in der Mitte der Steppe geblieben ist. Sie wurde verschlungen, als ihr eigener Than den Feuerfürsten herbeirief. Zerbrochene Mauern und eingestürzte Hallen schwelen noch immer in der Asche. Relikte der Stadt liegen verstreut im Schutt, und man sagt, sie bewahrten die Erinnerung an das, was hier geschah. Die Dunkeleisenzwerge haben den Ort nicht vergessen: Spione, Agenten und Feuerläufer ihres Imperators bewachen ihn, und Kriegshäscher wandeln durch seine Straßen. Irgendwo zwischen den Steinen liegt die Tafel der Sieben, geschrieben zum Lob von sieben Zwergen großen Wissens.]=],
		},
	},
})

Translate("deDE", "altar-of-storms-burning-steppes", {
	title = "Altar der Stürme (Brennende Steppe)",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Im äußersten Westen der Steppe, im Schatten des Berges, steht ein Altar der Stürme. Hexenmeister der {link:blackrock-mountain}Blackrock{/link} versammeln sich um ihn und vollziehen dort ihre Riten. Seine Macht zieht auch andere an. Der Hexenmeister {link:mor-zul-bloodbringer}Mor'zul Bloodbringer{/link} lagert in der Nähe mit seinem Diener {link:gorzeeki-wildeyes}Gorzeeki Wildeyes{/link} und erforscht die Energie des Altars für eigene Zwecke, und hierher kommen Hexenmeister zu ihm, wenn sie ein Ross der brennenden Ebenen von Xoroth an sich binden wollen.]=],
		},
	},
})

Translate("deDE", "pillar-of-ash", {
	title = "Die Aschensäule",
	aliases = { "Aschensäule" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Aschensäule ist ein hoher Turm der {link:blackrock-mountain}Blackrock{/link} im Süden der Steppe, der sich über die Lager erhebt, in denen die {link:orcs}Orcs{/link} ihre Soldaten und Worgs für den Marsch auf {link:redridge-mountains}Rotkamm{/link} sammeln. Zauberer und Schlächter patrouillieren auf dem Gelände darum. Westlich des {link:dreadmaul-rock}Schreckensfels{/link}, in einem Blackrockbau nahe der Säule, herrschte einst der Ogerlord {link:gor-tesh}Gor'tesh{/link} über die Firegut, fern dem Felsen, den seine {link:ogres}Oger{/link} bewachten.]=],
		},
	},
})

Translate("deDE", "terror-wing-path", {
	title = "Schreckenspfad",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schreckenspfad verläuft entlang der östlichen Klippen der Steppe, von den Hängen unterhalb von {link:morgan-s-vigil}Morgans Wacht{/link} bis in den äußersten Nordosten. Er ist das Jagdgebiet des schwarzen Drachenschwarms. Brutlinge wimmeln auf den unteren Hängen, Drachenbrut und Wyrmkin halten die Höhen, und schwarze Drachen kreisen darüber. Die Soldaten der Wacht müssen jeden Tag gegen diese Drachkin kämpfen, nur um ihren Grat zu halten. Jenseits des Pfades, an seinem nördlichen Ende, liegt die Höhle namens {link:slither-rock}Schlitterfels{/link}.]=],
		},
	},
})

Translate("deDE", "draco-dar", {
	title = "Draco'dar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Draco'dar ist eine Gegend versengter Hügel im Südwesten der Steppe. Sie gehört den Drachkin der flammenschuppigen Bruten, die stärker und wilder sind als ihre Verwandten im Osten. Sengschuppendrachen fliegen über {link:razorfen-downs}die Hügel{/link}, und ein großer Drache namens Hematos soll unter ihnen umherstreifen. Reisende betreten Draco'dar nicht allein, und nur wenige betreten es überhaupt.]=],
		},
	},
})

Translate("deDE", "slither-rock", {
	title = "Schlitterfels",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schlitterfels ist eine einsame Höhle im äußersten Nordostwinkel der Steppe, jenseits des Endes des Schreckenspfads. Ein einziges Geschöpf haust dort: {link:cyrus-therepentous}Cyrus Therepentous{/link}, ein Diener des schwarzen Drachenschwarms, der einen eigenen Drachen als {link:the-night-watch}Wächter{/link} hält. Besucher sind ihm nicht willkommen. Wen er nicht zu verschlingen beschließt, den nutzt er für seine Zwecke.]=],
		},
	},
})

Translate("deDE", "blackrock-pass", {
	title = "Blackrockpass",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Blackrockpass ist die Straße zwischen der Brennenden Steppe und dem {link:redridge-mountains}Rotkammgebirge{/link}, bewacht von einem Tor auf der Seite von Rotkamm. Durch ihn ziehen die Kriegstrupps der {link:blackrock-mountain}Blackrock{/link} südwärts, um über {link:lakeshire}Seenhain{/link} herzufallen, und durch ihn kommen Stormwinds Hilfssheriffs nordwärts nach {link:morgan-s-vigil}Morgans Wacht{/link}. Es ist eine scharfe Grenze. Auf der einen Seite liegen die roten Hügel und der See. Auf der anderen liegt Asche, und Geschöpfe des Feuers, die schon viele Reisende getötet haben, die sich zu weit vorwagten.]=],
		},
	},
})

Translate("deDE", "marshal-maxwell", {
	title = "Marschall Maxwell",
	subtitle = "Befehlshaber von Morgans Wacht",
	found = "Morgans Wacht, im Südosten der Steppe",
	hint = [=[Sprecht mit dem Marschall, der Stormwinds letzten Grat in der Brennenden Steppe hält.]=],
	allegiance = "Königreich Stormwind · Armee von Stormwind",
	aliases = { "Maxwell" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marschall Maxwell befehligt {link:morgan-s-vigil}Morgans Wacht{/link}, Stormwinds einzigen Stützpunkt in der Brennenden Steppe. Er übernahm den Befehl, als Marschall Windsor verloren ging, und er hält seinen Grat mit wenigen Soldaten gegen {link:orcs}Orcs{/link}, {link:ogres}Oger{/link} und Drachen. Er freut sich über jedes Mitglied der {link:alliance}Allianz{/link}, das so weit kommt. Er ist auch verbittert geworden. Er hat {link:stormwind-city}Stormwind{/link} viele Male um Hilfe gebeten, und Stormwind hat ihm Hilfssheriffs statt Heere geschickt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Maxwell steht an der Schwelle des Feindes. Von der Wacht aus kann er die {link:blackrock-stronghold}Festung der Blackrock{/link} und den Berg darüber sehen, und er weiß besser als irgendjemand in der {link:capital-city}Hauptstadt{/link}, was sich dort sammelt. Durch ihn wird die lange Suche nach Marschall Windsor und nach der Wahrheit, die Windsor bei sich trug, fortgesetzt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hält {link:morgan-s-vigil}Morgans Wacht{/link} gegen die Blackrockorcs, die {link:ogres}Oger{/link} der Firegut und die schwarzen Drachkin.
• Er schickt Hilfssheriffs aus, um das Schicksal von Marschall Windsor zu erfahren, zuerst von {link:ragged-john}Ragged John{/link}, dann in den Tiefen des {link:blackrock-mountain}Blackrock{/link}.
• Er plant den Krieg gegen die Herren der Blackrockspitze anhand der Karten und Berichte, die man ihm bringt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Maxwells Leben vor der Wacht ist wenig geschrieben, und über seine Familie nichts.]=],
		},
	},
	chapters = {
		{
			title = "Noch ein Hilfssheriff",
			hint = [=[Kommt als stellvertretender Hilfssheriff Stormwinds nach Morgans Wacht.]=],
			text = [=[Als der Hilfssheriff von {link:magistrate-solomon}Magistrat Solomon{/link} mit dem Erlass des Regenten eintraf, lachte Maxwell. Der Hilfssheriff war nicht der erste. {link:stormwind-city}Stormwind{/link} hatte schon andere geschickt, und es hatte sie einen nach dem anderen verloren, während das Königreich über Beweise stritt. Maxwell hatte solche Beweise einst in Reichweite gehabt. Marschall Windsor hatte einen großen Schatz an Wissen über die {link:blackrock-mountain}Blackrock{/link} gesammelt, und alles davon war mit ihm verschwunden. Maxwell schickte den Neuankömmling nach Norden, um den einzigen Mann zu finden, der an Windsors Seite gewesen war.]=],
		},
		{
			title = "Ein Marschall in Ketten",
			hint = [=[Erfahrt, was in den Tiefen des Blackrock aus Marschall Windsor wurde.]=],
			text = [=[{link:ragged-john}Ragged John{/link} schwor, dass Windsor lebte, ein Gefangener der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}. Maxwell schickte seinen Hilfssheriff in die {red:blackrock-depths}Blackrocktiefen{/red}, um den Marschall zurückzubringen oder einen Beweis seines Todes. Die Nachricht, die zurückkam, war schlimmer als beides. Windsor lebte, doch seine Aufzeichnungen waren verloren, und er faselte von Narren und verborgenen Feinden. Maxwell senkte das Haupt und trauerte um einen stolzen Krieger, der, wie er glaubte, den Verstand verloren hatte.]=],
		},
		{
			title = "Windsor befreit",
			hint = [=[Helft Marschall Windsor, aus dem Gefängnis der Dunkeleisenzwerge zu entkommen.]=],
			text = [=[Windsor war nicht wahnsinnig. Er kam mit seinen gestohlenen Aufzeichnungen in Händen aus dem Berg, und er zog wie ein Sturm durch {link:morgan-s-vigil}Morgans Wacht{/link}, auf dem Weg nach {link:stormwind-city}Stormwind{/link}. Er werde den Regenten zur Rede stellen, sagte er, und die Dame, die an der Seite des Regenten steht. Maxwell ließ ihm nachrichten, dass sein Hilfssheriff ihn an den Toren der Stadt treffen solle und nicht allein gehen dürfe. Was Windsor zu enthüllen gedachte, würde das Königreich in seinen Grundfesten erschüttern.]=],
		},
		{
			title = "Die Herren entlarvt",
			hint = "Seht die Große Maskerade bis zu ihrem Ende.",
			text = [=[Im Thronsaal von {link:stormwind-keep}Burg Stormwind{/link} legte Windsor dem Hof seine Beweise vor, und {link:katrana-prestor}Lady Katrana Prestor{/link} warf ihre menschliche Gestalt ab. Sie war {link:onyxia}Onyxia{/link}, Tochter von {link:deathwing}Todesschwinge{/link}, und solange sie den Regenten beraten hatte, hatte der schwarze Drachenschwarm das Ohr Stormwinds besessen. Windsor starb dort. In der Wacht verstand Maxwell endlich, warum seine Bitten unbeantwortet geblieben waren. Die Drachen hatten die {link:blackrock-mountain}Blackrock{/link} vom Berg aus befehligt, und sie hatten {link:stormwind-city}Stormwind{/link} an seinem eigenen Hof zum Schweigen gebracht.]=],
		},
		{
			title = "Krieg gegen die Spitze",
			hint = [=[Bringt Maxwell Nachricht von denen, die die Blackrockspitze wirklich befehligen.]=],
			text = [=[Eine Goblinspionin, die sich durch die Spitze geschlichen hatte, schickte Maxwell eine Karte. Sie bestätigte, was er vermutete. Die {link:blackrock-mountain}Blackrock{/link} waren Lasttiere und Futter für den schwarzen Drachenschwarm, und ihr wahrer Herr war {red:nefarian}Nefarian{/red}, Sohn von {link:deathwing}Todesschwinge{/link}. Maxwell bestimmte den Kriegsmeister, den Ogerhochlord und den Oberherrn der Zitadelle zum Tode. Später wurde der Leiche eines Drachkin in der Spitze ein Brief abgenommen, geschrieben von seinem Vorgesetzten, {red:general-drakkisath}General Drakkisath{/red}. Maxwell bestimmte auch den General zum Tode. Er sagte, der Krieg werde an zwei Fronten geführt: in {link:stormwind-city}Stormwind{/link} selbst und hier, am Tor des Feindes.]=],
		},
	},
	mentions = {
		{
			text = [=[Die wahren Herren, von {link:magistrate-solomon}Magistrat Solomon{/link}]=],
		},
		{
			text = [=[Die wahren Herren, die Geschichte von {link:ragged-john}Ragged John{/link}]=],
		},
		{ text = "Marschall Windsor" },
		{ text = "Verlorene Hoffnung" },
		{ text = "Gefängnisausbruch!, der an seinem Posten endet" },
		{ text = "Treffen in {link:stormwind-city}Stormwind{/link}" },
		{ text = "Nachricht an Maxwell" },
		{ text = "Maxwells Mission" },
		{ text = "General Drakkisaths Befehl" },
		{ text = "General Drakkisaths Ende" },
	},
	bonds = {
		{ id = "reginald-windsor", name = "Reginald Windsor", note = "sein verlorener Befehlshaber" },
		{ id = "ragged-john", name = "Ragged John", note = "ein Zeuge, den er einen Feigling nennt" },
		{ id = "magistrate-solomon", name = "Magistrat Solomon", note = "schickt ihm Hilfssheriffs" },
		{ id = "helendis-riverhorn", name = "Helendis Riverhorn", note = "sein Späher" },
		{ id = "oralius", name = "Oralius", note = "ein Soldat der Wacht" },
		{ id = "nefarian", name = "Nefarian", note = "der wahre Herr der Spitze" },
	},
})

Translate("deDE", "helendis-riverhorn", {
	title = "Helendis Riverhorn",
	subtitle = "Späher von Morgans Wacht",
	found = "Der Ostrand von Morgans Wacht, über den Hängen der Drachkin",
	hint = [=[Sprecht mit dem Nachtelfen, der vom Rand von Morgans Wacht aus die Drachkin beobachtet.]=],
	allegiance = "Allianz · Morgans Wacht",
	aliases = { "Helendis" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Helendis Riverhorn ist ein {link:night-elves}Nachtelf{/link}, der in {link:morgan-s-vigil}Morgans Wacht{/link} dient. Er steht am Rand des Grats, über den Hängen, an denen sich die schwarzen Drachkin sammeln, und beobachtet sie. Er ruft {link:cenarius}Cenarius{/link} an, wenn er einem Soldaten Gutes wünscht. Er war es, der zuerst klar erkannte, was die Blackrockorcs wirklich waren, und der dieses Wissen südwärts nach {link:lakeshire}Seenhain{/link} schickte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Helendis setzte die Kette von Ereignissen in Gang, die eines Tages den Thronsaal von {link:stormwind-city}Stormwind{/link} erreichen sollte. Die {link:humans}Menschen{/link} hatten stets geglaubt, die {link:blackrock-mountain}Blackrock{/link} seien von Natur aus wild. Helendis fand heraus, dass sie getrieben wurden. Die Wut, die sie erfüllt, schrieb er, werde vom schwarzen Drachenschwarm genährt, und die Drachen seien ihre wahren Herren.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kämpft gegen die Drachkin, die {link:morgan-s-vigil}die Wacht{/link} bedrängen.
• Er schreibt {link:magistrate-solomon}Magistrat Solomon{/link} von den wahren Herren der {link:blackrock-mountain}Blackrock{/link}.
• Er verfolgt die endlosen Rudel der Blackrockworgs bis zu ihrem Ursprung.]=],
		},
	},
	chapters = {
		{
			title = "Drachkin unter dem Grat",
			hint = "Drängt die Drachkin unterhalb von Morgans Wacht zurück.",
			text = [=[Helendis wollte mit einem Fremden nicht über ernste Dinge sprechen. Zuerst musste der Fremde beweisen, dass er gegen Drachkin bestehen konnte. Erst als Brutlinge, Drachenbrut, Wyrmkin und ein Drache an den Hängen darunter gefallen waren, hielt er den Neuankömmling für bereit, mehr zu hören.]=],
		},
		{
			title = "Ein Brief nach Seenhain",
			hint = "Bringt Helendis' Brief südwärts nach Seenhain.",
			text = [=[Was Helendis in der Heimat der {link:blackrock-mountain}Blackrock{/link} gefunden hatte, konnte nicht auf einem einzigen Grat bleiben. Er versiegelte einen Brief an {link:magistrate-solomon}Magistrat Solomon{/link}: Die {link:orcs}Orcs{/link} waren nicht ihre eigenen Herren, und es war der schwarze Drachenschwarm, der sie mit Wut erfüllte. Solomon weinte, als er las, was das für seine Stadt bedeutete, und er schickte ihn weiter nach {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "Die Worgmutter",
			hint = "Sucht den Ursprung der Worgs in der Blackrockspitze.",
			text = [=[Die Blackrockworgs wurden nie weniger, wie viele auch erschlagen wurden. Helendis' Späher erfuhren, dass die Tiere in der Spitze gezüchtet und abgerichtet wurden. Er schickte einen Jäger aus, um den Ursprung zu finden, und er rief ihm einen Namen nach, als der Jäger aufbrach: Halycon. Sie war ein Geschöpf dunkler Magie, und Helendis bat, dass niemand um sie trauere.]=],
		},
	},
	mentions = {
		{ text = "Bedrohung durch Drachkin" },
		{ text = "Die wahren Herren" },
		{ text = "Erlöst sie" },
	},
	bonds = {
		{ id = "magistrate-solomon", name = "Magistrat Solomon", note = "erhielt seinen Brief" },
		{ id = "marshal-maxwell", name = "Marschall Maxwell", note = "sein Befehlshaber" },
		{ id = "katrana-prestor", name = "Katrana Prestor", note = "hörte seine Warnung aus zweiter Hand" },
	},
})

Translate("deDE", "ragged-john", {
	title = "Ragged John",
	subtitle = "Zeuge des Berges",
	found = "Flammenkamm, unter dem nördlichen Grat",
	hint = [=[Sucht den betrunkenen Zwerg, der sich in einer Höhle am Flammenkamm verbirgt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ragged John ist ein {link:dwarves}Zwerg{/link}, der am {link:flame-crest}Flammenkamm{/link} lebt, in der Höhle unter dem nördlichen Grat, und er ist selten nüchtern. Er war an Marschall Windsors Seite an dem Tag, als der Marschall verschwand. {link:marshal-maxwell}Marschall Maxwell{/link} nennt ihn einen Feigling. John sagt lieber, er sei ein wenig schlampig, und Zwerge würden niemals betrunken.]=],
		},
		{
			title = "Bedeutung",
			text = [=[John ist der einzige Zeuge von Windsors Schicksal. Seine Geschichte, so schwer ihr auch zu folgen ist, verriet {link:morgan-s-vigil}Morgans Wacht{/link}, dass Windsor noch lebte und wo man nach ihm suchen musste.]=],
		},
		{
			title = "Taten",
			text = [=[• Er marschierte mit Marschall Windsor in den {link:blackrock-mountain}Blackrock{/link}.
• Er schlüpfte in die Schatten, als die {link:orcs}Orcs{/link} angriffen.
• Er geht hin und wieder in die Blackrockspitze und lauscht, was die Orcs sagen.]=],
		},
	},
	chapters = {
		{
			title = "Die Geschichte von Ragged John",
			hint = "Hört von Ragged John, was Marschall Windsor widerfuhr.",
			text = [=[John erzählt sie ausführlich. Windsor war an jenem Tag finsterer Laune und sagte immer wieder, etwas fühle sich falsch an. Im Herzen des Berges fielen die {link:blackrock-mountain}Blackrock{/link} über sie her, und John versteckte sich. Windsor hielt mit Ironfoe stand, dem orctötenden Hammer, den {link:franclorn-forgewright}Franclorn Forgewright{/link} für einen seiner Vorfahren geschmiedet hatte, und er stand noch, getränkt in Orcblut, als die Kämpfe endeten. Dann kamen die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}, zu Hunderten. Sie töteten ihn nicht, vielleicht weil sein Vorfahr ein Freund ihres Volkes gewesen war. Sie nahmen ihn gefangen, und ihr Anführer nahm Ironfoe an sich. John sah ihn nie wieder.]=],
		},
		{
			title = "Muttermilch",
			hint = [=[Bringt Ragged John eine lebendige Probe des tödlichsten Giftes der Spitze.]=],
			text = [=[In der Spitze hörte John die {link:orcs}Orcs{/link} von einem Gift sprechen, das sie Muttermilch nennen, nach der großen Spinne Mother Smolderweb. Er wollte es haben, und nicht aus einer Drüse: Es musste frisch sein, in den Adern von jemandem, den sie gebissen hatte. Als er es herausgezogen hatte, erklärte er, es werde sein bisher bestes Bier ergeben.]=],
		},
	},
	mentions = {
		{ text = "Die wahren Herren" },
		{ text = "Muttermilch" },
	},
	bonds = {
		{ id = "reginald-windsor", name = "Reginald Windsor", note = "der Marschall, mit dem er marschierte" },
		{ id = "marshal-maxwell", name = "Marschall Maxwell", note = "nennt ihn einen Feigling" },
		{ id = "franclorn-forgewright", name = "Franclorn Forgewright", note = "schmiedete Windsors Hammer" },
	},
})

Translate("deDE", "oralius", {
	title = "Oralius",
	subtitle = "Soldat von Morgans Wacht",
	found = "Morgans Wacht",
	hint = [=[Sprecht mit dem Zwerg in Morgans Wacht, der mit einem Freund redet, den sonst niemand sehen kann.]=],
	allegiance = "Königreich Stormwind · Morgans Wacht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oralius ist ein zwergischer Soldat von {link:morgan-s-vigil}Morgans Wacht{/link}, der den Krieg gegen die {link:ogres}Oger{/link} der Firegut mit großem Eifer plant. Er spricht auch mit Hauptmann Winky, einem Freund, den sonst niemand sehen kann, und er sammelt Ogerohren. Er vertraut einem an, er sei der einzige Vernünftige in der Wacht. Die anderen sehen das anders.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Was auch immer der Krieg seinem Verstand genommen hat, seinen Hass auf den Feind hat Oralius nicht verloren. Sein Feldzug gegen den {link:dreadmaul-rock}Schreckensfels{/link} ist der härteste Schlag, den {link:morgan-s-vigil}die Wacht{/link} geführt hat.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befiehlt Angriffe gegen die {link:ogres}Oger{/link} der Firegut am {link:dreadmaul-rock}Schreckensfels{/link}.
• Er bestimmt den Ogerlord {link:gor-tesh}Gor'tesh{/link} zum Tode.
• Er sammelt die Medaillons von Blackrockorcs als Ergänzung zu seinen Ogerohren.]=],
		},
	},
	chapters = {
		{
			title = "Ein Kopf auf einer Pike",
			hint = "Helft Oralius, den Mut der Oger der Firegut zu brechen.",
			text = [=[Als {link:gor-tesh}Gor'tesh{/link} fiel, steckte Oralius den Kopf des Ogerlords auf eine Pike und ließ ihn auf die Spitze des {link:dreadmaul-rock}Schreckensfels{/link} tragen, überzeugt, dass der Anblick die {link:ogres}Oger{/link} in Panik fliehen lassen würde. Hinterher fragte er, ob jemand ein Bild davon gemalt habe.]=],
		},
	},
	mentions = {
		{ text = "Löscht die Firegut aus" },
		{ text = "{link:gor-tesh}Gor'tesh{/link} der Rohlingslord" },
		{ text = "Ogerkopf am Stock = Feier" },
		{ text = "FÜNFZIG! JAWOLL!" },
		{ text = "Das gute Zeug" },
	},
	bonds = {
		{ id = "gor-tesh", name = "Gor'tesh", note = "der Ogerlord, den er zum Tode bestimmte" },
		{ id = "marshal-maxwell", name = "Marschall Maxwell", note = "sein Befehlshaber" },
	},
})

Translate("deDE", "jalinda-sprig", {
	title = "Jalinda Sprig",
	subtitle = "Gnomische Magierin von Morgans Wacht",
	found = "Morgans Wacht",
	hint = [=[Sprecht mit der Gnomin in Morgans Wacht, deren Magier immer wieder versengt aus dem Berg zurückkehren.]=],
	allegiance = "Allianz · Morgans Wacht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jalinda Sprig ist eine Gnomin in {link:morgan-s-vigil}Morgans Wacht{/link}, die eine Expedition von Magiern in den {link:blackrock-mountain}Blackrock{/link} führt. Oder es versucht. Die letzten fünf, die sie aussandte, kamen verbrannt zurück, wenn sie überhaupt zurückkamen. Sie ist ängstlich und gütig, und sie befürchtet schnell das Schlimmste.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jalindas Expedition war unter den ersten, die erfuhren, dass die Feuer unter dem Berg einen Herrn haben.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie will ihrer Expedition den Weg in die {red:blackrock-depths}Blackrocktiefen{/red} öffnen.
• Sie schickt Hilfe gegen {link:overmaster-pyron}Obermeister Pyron{/link}, der den Steinbruch des Berges bewacht.]=],
		},
	},
	chapters = {
		{
			title = "Incendius",
			hint = "Erfahrt, wer Pyron aus der Asche erweckt.",
			text = [=[{link:overmaster-pyron}Pyron{/link} sprach im Sterben einen Namen: Incendius. Jalinda kannte ihn, und sie schluckte schwer. Lord Incendius sollte {red:ragnaros}Ragnaros{/red} dienen. Als die Nachricht zurückkam, dass Incendius selbst den Feuerfürsten genannt hatte, sagte sie nichts mehr und versank tief in Gedanken.]=],
		},
	},
	mentions = {
		{ text = "{link:overmaster-pyron}Obermeister Pyron{/link}" },
		{ text = "Incendius!" },
	},
	bonds = {
		{ id = "overmaster-pyron", name = "Obermeister Pyron", note = "der Wächter des Steinbruchs" },
		{ id = "ragnaros", name = "Ragnaros", note = "der Name, den sie fürchtet" },
	},
})

Translate("deDE", "mayara-brightwing", {
	title = "Mayara Brightwing",
	subtitle = "Agentin von Graf Ridgewell",
	found = "Morgans Wacht",
	hint = [=[Sprecht mit der Frau in Morgans Wacht, die einem Sammler in Stormwind dient.]=],
	allegiance = "Haus Ridgewell",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mayara Brightwing ist eine Agentin von {red:count-remington-ridgewell}Graf Remington Ridgewell{/red}, einem Adligen aus {link:stormwind-city}Stormwind{/link}, der ein Familienmuseum unterhält. Er schickte sie in {link:burning-steppes}die Steppe{/link}, um {link:ruins-of-thaurissan}die Ruinen von Thaurissan{/link} nach Kunstgegenständen zu durchsuchen. Was sie fand, liegt anderswo: hoch oben in der Blackrockspitze, in einer Halle, in der die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} einst ihre Schätze aufbewahrten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Selbst in der Brennenden Steppe haben die Adligen Stormwinds ihre Agenten. Mayara dient den Sammlungen des Adelshauses, während Soldaten um ihr Leben kämpfen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie erkundete {link:ruins-of-thaurissan}die Ruinen von Thaurissan{/link} für ihren Gönner.
• Sie sucht Doomriggers Spange, ein juwelenbesetztes Relikt, das in der alten Hall of Fortune der Spitze zurückblieb.]=],
		},
	},
	mentions = {
		{ text = "Mayara Brightwing" },
		{ text = "Doomriggers Spange" },
		{ text = "Lieferung an Ridgewell" },
	},
	bonds = {
		{ id = "count-remington-ridgewell", name = "Graf Remington Ridgewell", note = "ihr Gönner" },
	},
})

Translate("deDE", "maxwort-uberglint", {
	title = "Maxwort Uberglint",
	subtitle = "Sucher der Sieben",
	found = "Flammenkamm",
	hint = [=[Sprecht mit dem Schatzsucher am Flammenkamm, der den Legenden der Sieben folgt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Maxwort Uberglint wurde von den alten Geschichten über die Sieben, {link:dwarves}Zwerge{/link} großen Wissens und großer Macht, in die {link:burning-steppes}Brennende Steppe{/link} gelockt. Er macht keinen Hehl daraus, warum. Wissen und Macht bringen Reichtum, und Reichtum ist, was er will. Er begehrt auch einen Edelstein, den die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} in ihrem Gewölbe verwahren, einen Stein so groß wie eine Faust.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Maxwort hält eine alte Geschichte Thaurissans lebendig. Die Tafel der Sieben liegt noch in den Ruinen, und er will ihre Worte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sucht eine Abschrift der Tafel der Sieben in den Ruinen von {link:ruins-of-thaurissan}Thaurissan{/link}.
• Er hat jahrelang versucht, den Dunkeleisenzwergen das Herz des Berges abzukaufen, und ist gescheitert.]=],
		},
	},
	mentions = {
		{ text = "Die Tafel der Sieben" },
		{ text = "Das Herz des Berges" },
	},
	bonds = {
		{ id = "mathredis-firestar", name = "Mathredis Firestar", note = "teilt das Lager am Flammenkamm" },
	},
})

Translate("deDE", "yuka-screwspigot", {
	title = "Yuka Screwspigot",
	subtitle = "Schwester von Ribbly",
	found = "Flammenkamm",
	hint = [=[Sprecht mit der Goblin am Flammenkamm, die ihren eigenen Bruder jagt.]=],
	allegiance = "Die Familie Screwspigot",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Yuka Screwspigot ist zum {link:flame-crest}Flammenkamm{/link} gekommen, um ihren Bruder Ribbly zu finden. Ribbly hat das Geld der Familie für einen Plan nach dem anderen verschwendet, und sein letzter Plan hat ihm ein Kopfgeld von {link:baron-revilgaz}Baron Revilgaz{/link} aus {link:booty-bay}Booty Bay{/link} eingebracht. Zum ersten Mal in seinem Leben ist Ribbly etwas wert. Yuka will es kassieren.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Screwspigots zeigen, dass Familie für manche Goblins eine Frage der Buchführung ist. Ribbly ist in die {red:blackrock-depths}Blackrocktiefen{/red} geflohen, und seine Schwester ist ihm bis vor die Tür gefolgt.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie verfolgte Ribbly bis in die {link:burning-steppes}Brennende Steppe{/link} und ließ nach angeheuerten Helfern schicken.
• Sie wird ihren Bruder lebend nehmen, oder seinen Kopf, wenn er sich weigert mitzukommen.]=],
		},
	},
	mentions = {
		{ text = "Yuka Screwspigot, von ihrer Verwandten Yorba" },
		{ text = "Ribbly Screwspigot" },
	},
	bonds = {
		{ id = "baron-revilgaz", name = "Baron Revilgaz", note = "setzte das Kopfgeld auf Ribbly aus" },
	},
})

Translate("deDE", "tinkee-steamboil", {
	title = "Tinkee Steamboil",
	subtitle = "Gelehrte der Drachkin",
	found = "Flammenkamm",
	hint = [=[Sprecht mit der Erfinderin am Flammenkamm, die die Drachkin der Steppe erforscht.]=],
	allegiance = "Ein verborgener Gönner",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tinkee Steamboil ist eine Erfinderin, die wochenlang vom {link:flame-crest}Flammenkamm{/link} aus die Drachkin der Steppe erforscht hat. Ihre Geräte fangen die Essenz von Brutlingen ein und frieren die Eier schwarzer Drachen ein. Sie träumt davon, von den Drachengelehrten der ganzen Welt beneidet zu werden. Sie dient auch einem Gönner, den sie nicht nennen will, und sie warnt, dass man ihn besser nicht enttäuscht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tinkees Arbeit sollte die Eier des schwarzen Drachenschwarms in gefährliche Hände liefern. Dass es nicht dazu kam, war nicht ihr Verdienst.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie baute den Draco-Incarcinatrix 900, um die Essenz von Brutlingen zu entziehen.
• Sie suchte bei {link:felnok-steelspring}Felnok Steelspring{/link} in {link:everlook}Everlook{/link} nach Teilen, um Dracheneier einzufrieren.
• Sie schickte Suchende in die Brutstätte der Blackrockspitze, um Eier zu holen.]=],
		},
	},
	chapters = {
		{
			title = "Die Eier des Meisters",
			hint = [=[Bringt die gefrorenen Eier dorthin, wohin Tinkees Meister es verlangt.]=],
			text = [=[Eine Nachricht kam, angeblich von ihrem Meister Vectus. Unterzeichnet war sie von einem Mann, von dem sie nie gehört hatte: {link:leonid-barthalomew}Leonid Barthalomew{/link}, in der {link:light-s-hope-chapel}Kapelle des hoffnungsvollen Lichts{/link}. Tinkee war gekränkt, dass ihr Meister einem anderen die Eier anvertraute, doch sie schickte sie. Leonid war kein Diener des Vectus. Er war ein Ritter der {link:argent-dawn}Argentumdämmerung{/link}, und er hatte sie getäuscht, damit die Eier niemals die Macht erreichten, der sie gedient hatte.]=],
		},
	},
	mentions = {
		{ text = "Brutlingsessenz" },
		{ text = "{link:felnok-steelspring}Felnok Steelspring{/link}" },
		{ text = "Zurück zu Tinkee" },
		{ text = "Tinkee Steamboil" },
		{ text = "Eier einfrieren" },
		{ text = "Eier sammeln" },
		{ text = "{link:leonid-barthalomew}Leonid Barthalomew{/link}" },
	},
	bonds = {
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "täuschte sie" },
		{ id = "felnok-steelspring", name = "Felnok Steelspring", note = "ihr Kollege" },
	},
})

Translate("deDE", "kibler", {
	title = "Kibler",
	subtitle = "Händler exotischer Haustiere",
	found = "Flammenkamm, zwischen seinen Käfigen",
	hint = [=[Sucht den Haustierhändler zwischen den Käfigen am Flammenkamm.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kibler nennt sich in erster Linie Tierfreund und von Beruf Verkäufer. Er jagt exotische Bestien für die Reichen und Berühmten und zähmt sie zu anständigen Haustieren. Am {link:flame-crest}Flammenkamm{/link} hält er seine Käfige, streitet mit seinem Tukan und kauft Worgwelpen und Spinneneier aus der Spitze.]=],
