Translate("deDE", "mathredis-firestar", {
	title = "Mathredis Firestar",
	subtitle = "Sucher der verlorenen Buchbände",
	found = "Flammenkamm",
	hint = [=[Sucht den Elfen am Flammenkamm auf, der nach verlorenen Buchbänden sucht.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mathredis Firestar ist ein Elf aus {link:quel-thalas}Quel'Thalas{/link}, der nach Buchbänden sucht, die von den elfischen Meistern geschrieben wurden. Sie wurden über die ganze Welt verstreut, als die {link:scourge}Geißel{/link} über seine Heimat herfiel. Vor allem sucht er die zehn, die sein Meister Telmius Dreamseeker schrieb. Gibt man ihm einen Buchband, nimmt er dessen Magie in sich auf und fertigt im Gegenzug einen Zauber der Macht. Sein Preis ist hoch, und er macht kein Geheimnis daraus.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mathredis trägt die Trauer und den Hunger eines gefallenen Volkes. Was sein Meister schrieb, überlebt nun auf verstreuten Seiten, und er will aus jeder einzelnen schöpfen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er fertigt Zauber aus wiedergefundenen Buchbänden, im Tausch gegen seltene Bestandteile und Gold.]=],
		},
	},
	mentions = {
		{ text = "Buchband des Nachsinnens" },
		{ text = "Buchband der Konstitution" },
		{ text = "Buchband der Hartnäckigkeit" },
		{ text = "Buchband der Widerstandsfähigkeit" },
		{ text = "Buchband der Gier" },
	},
	bonds = {
		{ id = "maxwort-uberglint", name = "Maxwort Uberglint", note = "teilt das Lager" },
	},
})

Translate("deDE", "cyrus-therepentous", {
	title = "Cyrus Therepentous",
