	},
})

Translate("deDE", "mor-zul-bloodbringer", {
	title = "Mor'zul Bloodbringer",
	subtitle = "Hexenmeister vom Altar der Stürme",
	found = [=[Ein Lager nahe dem Altar der Stürme, im äußersten Westen der Steppe]=],
