	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mor'zul Bloodbringer ist ein Hexenmeister, der sein Lager nahe dem Altar der Stürme aufgeschlagen hat, um dessen Energie zu erforschen. Er kennt das Ritual, das ein Schreckensross aus den feurigen Ebenen von Xoroth herbeiruft und es an einen Herrn bindet. Er lehrt es nur Hexenmeistern großer Macht, und nur gegen einen hohen Preis in Blut und Gold. Er liebt Blut, und man sagt, er genieße seinen Geschmack.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mor'zul ist ein Hüter verbotenen Wissens. Durch ihn führt der Weg nach Xoroth von der Steppe bis in den Schnee von {link:winterspring}Winterspring{/link} und zum Sitz des Schattenrats im {link:felwood}Teufelswald{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erforscht den Altar der Stürme.
• Er zeichnet die Glyphen, die ein Schreckensross von Xoroth herbeirufen, mit Tinte aus dem Blut rasender Eulenbestien.]=],
		},
	},
	mentions = {
		{ text = "Mor'zul Bloodbringer" },
		{ text = "Blutrausch" },
		{ text = "Wildeyes" },
		{ text = "Schreckensross von Xoroth" },
	},
	bonds = {
		{ id = "gorzeeki-wildeyes", name = "Gorzeeki Wildeyes", note = "sein Diener" },
	},
})

