Translate("deDE", "grark-lorkrub", {
	title = "Grark Lorkrub",
	subtitle = "Verräter von Kargath",
	found = "Festung der Blackrock",
	hint = [=[Sucht den Orc, der die Horde verriet und sich in der Festung der Blackrock verbirgt.]=],
	allegiance = "Blackrockklan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grark Lorkrub ist ein {link:orcs}Orc{/link} der {link:horde}Horde{/link}, der dabei ertappt wurde, wie er den {link:blackrock-mountain}Blackrock{/link} Nachrichten über die täglichen Arbeiten im Außenposten der Horde in {link:kargath}Kargath{/link} zukommen ließ. Er floh über die {link:searing-gorge}Sengende Schlucht{/link}, durch den Berg und in {link:burning-steppes}die Steppe{/link}, und nun sitzt er unter dem Schutz des Klans in der {link:blackrock-stronghold}Festung der Blackrock{/link}. Er glaubt, die Blackrock würden ihn stark machen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Grark zeigt, welche Anziehung die alte {link:horde}Horde{/link} noch auf manche {link:orcs}Orcs{/link} Thralls ausübt. Er sieht Macht in der Legion der {link:blackrock-mountain}Blackrock{/link}, und er kann nicht verstehen, warum andere das nicht tun.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verriet die Unternehmungen der {link:horde}Horde{/link} in {link:kargath}Kargath{/link} an die {link:blackrock-mountain}Blackrock{/link}.]=],
		},
	},
	mentions = {
		{ text = "Grark Lorkrub" },
		{ text = "Eine prekäre Lage" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "der Kriegshäuptling, den er verriet" },
	},
})

