Translate("deDE", "krom-grul", {
	title = "Krom'Grul",
	subtitle = "Oger vom Schreckensfels",
	found = "Die Höhlen und Minen des Schreckensfels",
	hint = [=[Stellt Euch dem Oger, der in den Höhlen des Schreckensfels lauert.]=],
	allegiance = "Oger der Firegut",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Krom'Grul ist ein {link:ogres}Oger{/link} vom {link:dreadmaul-rock}Schreckensfels{/link}, der den Hinterhalt gegen einen Trupp der {link:horde}Horde{/link} anführte, der ausgesandt worden war, um mehr über die Riten der Firegut zu erfahren. Er erschlug sie alle bis auf eine, Sha'ni Proudtusk, die er für einen eigenen Ritus zurückbehielt. Er kettete sie an einen Altar und folterte sie, bis sie starb. Dann riss er ihr den Ehering aus dem Gesicht und trug ihn an seinem Finger.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Krom'Gruls Grausamkeit zeigt, was die Riten der Firegut verlangen. Sha'nis Gatte, {link:thal-trak-proudtusk}Thal'trak Proudtusk{/link}, dient in {link:kargath}Kargath{/link} im {link:badlands}Ödland{/link}. Es sollte ihr letzter Auftrag sein, und sie wollten sich gemeinsam ein Heim im {link:the-hinterlands}Hinterland{/link} schaffen.]=],
		},
	},
	mentions = {
		{ text = "{link:dreadmaul-rock}Schreckensfels{/link}" },
		{ text = "Krom'Grul" },
	},
})
